'use strict';
// LIBRA memory lens: live data → GUI. Lens notes are generated by a real chat model (and real
// embeddings) on the test VM host, the resulting storage is loaded into the shipped plugin in
// Chromium, and every displayed value is compared with the engine's own view of the same data:
//   - lens tab: one card per note, its label/text/quote, the person row (names, roles, unknown),
//     the time row (source wording or unknown), person chips and their counts and filters, search,
//     and every provenance fold (quote, time and name highlighted in the right turn);
//   - lens studio: card chips and the run log counts;
//   - recall: the actual request hook delivers lens lines, and the recall viewer lists the same
//     notes with their meaning scores;
//   - layout at 1280 and 390 px: no horizontal overflow, no touching buttons, no page errors.
// Env as libra_lens_live_eval.cjs (RAG_EVAL_LLM_*, RAG_EVAL_EMBED_*); CHROME_PATH for Chromium.
// --json file writes the report (outside the repository). No storage or key is written to disk.
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const { chromium } = require('playwright');
const { lensFixture } = require('../../tests/fixtures/libra_lens_handoff_fixture.cjs');
const { settings } = require('../../tests/browser/libra_approved_browser.cjs');
const corpus = require('./libra_lens_live_corpus.json');

const argv = process.argv.slice(2);
const jsonOut = argv.includes('--json') ? argv[argv.indexOf('--json') + 1] : null;
const llmUrl = String(process.env.RAG_EVAL_LLM_URL || '').replace(/\/+$/, '');
const embedUrl = String(process.env.RAG_EVAL_EMBED_URL || '').replace(/\/+$/, '');
if (!llmUrl || !embedUrl) throw new Error('RAG_EVAL_LLM_URL and RAG_EVAL_EMBED_URL are required');
if (jsonOut && !path.relative(path.resolve(__dirname, '../../..'), path.resolve(jsonOut)).startsWith('..')) throw new Error('Write the report outside the repository');
const plain = value => JSON.parse(JSON.stringify(value));
const norm = value => String(value || '').replace(/\s+/g, ' ').trim();
const report = { model: process.env.RAG_EVAL_LLM_MODEL, embedModel: process.env.RAG_EVAL_EMBED_MODEL, startedAt: new Date().toISOString(), datasets: {}, checks: [], failures: [] };
const check = (name, ok, detail = '') => { report.checks.push({ name, ok: Boolean(ok), detail }); if (!ok) report.failures.push(`${name}${detail ? ` — ${detail}` : ''}`); console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail && !ok ? ` — ${detail}` : ''}`); };

const callModel = async args => {
  const request = args[0] || {};
  const messages = (request.messages || request.prompt || []).map(m => ({ role: m.role === 'char' ? 'assistant' : m.role, content: String(m.content ?? '') }));
  for (let attempt = 0; attempt < 3; attempt += 1) {
    try {
      const response = await fetch(llmUrl + '/chat/completions', { method: 'POST', headers: { Authorization: `Bearer ${process.env.RAG_EVAL_LLM_KEY || ''}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: process.env.RAG_EVAL_LLM_MODEL, messages, temperature: 0, stream: false }), signal: AbortSignal.timeout(180000) });
      if (!response.ok) throw new Error(`${response.status}`);
      return { type: 'success', result: String((await response.json()).choices?.[0]?.message?.content || '') };
    } catch (error) { if (attempt === 2) return { type: 'error', result: String(error.message || error) }; await new Promise(resolve => setTimeout(resolve, 3000 * (attempt + 1))); }
  }
};
const embeddingConfig = { enabled: true, provider: 'openai', url: embedUrl + '/embeddings', model: process.env.RAG_EVAL_EMBED_MODEL, key: process.env.RAG_EVAL_EMBED_KEY, maxRetries: 2 };
const persona = { selectedPersona: 0, personas: [{ id: 'gui-persona', name: corpus.personaName }] };

// ---- 1. generate with the live model ------------------------------------------------------------
const runUntilStored = async (f, lensId, startTurn, endTurn) => {
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const result = plain(await f.api.runLensForRange(lensId, { startTurn, endTurn }));
    if (result.status !== 'failed') return result;
    console.log(`  T${startTurn}-T${endTurn} failed (${result.reason}); retry`);
  }
  throw new Error(`lens run T${startTurn}-T${endTurn} kept failing`);
};
const seedOf = (f, chatIndex) => ({ values: [...f.r.values], chat: f.character.chats[chatIndex], character: { ...f.character, chats: f.character.chats }, index: chatIndex });
const generateCorpus = async () => {
  const f = await lensFixture();
  try {
    f.control.onCall = callModel;
    f.r.context.risuai.nativeFetch = (url, init) => fetch(url, init);
    f.r.context.risuai.getDatabase = async () => persona;
    await f.api.saveEmbeddingSettings(embeddingConfig);
    const chat = f.target('lens GUI live');
    corpus.turns.forEach(([user, assistant], index) => chat.message.push({ role: 'user', chatId: `t${index + 1}-u`, data: user }, { role: 'char', chatId: `t${index + 1}-a`, data: assistant }));
    chat.messages = chat.message;
    f.character.name = corpus.characterName;
    const health = plain(await f.api.createLens({ name: '생체 추적', evidenceMode: 'interpretive', trackTime: true, trackSubject: true, cadence: { mode: 'manual' },
      labels: ['증상', '수치', '주기', '회복'], instruction: { goal: '등장하는 모든 존재(사람과 동물)의 몸 상태, 증상, 생체 수치, 생리 주기, 회복을 기록하라.' } }));
    const template = f.api.getLensStarterTemplates().find(row => row.templateId === 'starter_unresolved_promises');
    const promises = plain(await f.api.createLens({ ...template, lensId: template.templateId, cadence: { mode: 'manual' } }));
    for (const lens of [health, promises]) for (const [start, end] of [[1, 5], [6, 10]]) {
      const result = await runUntilStored(f, lens.lensId, start, end);
      console.log(`corpus ${lens.name} T${start}-T${end}: ${result.status} ${result.acceptedCount}`);
    }
    for (const lens of [health, promises]) console.log(`vectors ${lens.name}: ${JSON.stringify(plain(await f.api.refreshLensVectors({ lensId: lens.lensId })))}`);
    const truth = plain(await f.api.inspectScopeLenses());
    return { seed: seedOf(f, f.character.chats.length - 1), truth, lensIds: { health: health.lensId, promises: promises.lensId } };
  } finally { await f.close(); }
};
// The fixture's own chat already has canonical memory, so the request hook runs the full recall.
const generateRecall = async () => {
  const f = await lensFixture();
  try {
    f.control.onCall = callModel;
    f.r.context.risuai.nativeFetch = (url, init) => fetch(url, init);
    f.r.context.risuai.getDatabase = async () => ({ selectedPersona: 0, personas: [{ id: 'gui-persona', name: '사용자' }] });
    await f.api.saveEmbeddingSettings(embeddingConfig);
    const lens = plain(await f.api.createLens({ name: '물건과 약속', evidenceMode: 'interpretive', trackTime: true, trackSubject: true, cadence: { mode: 'manual' },
      instruction: { goal: '누가 어떤 물건을 가지고 있고 누구에게 넘겼는지, 누가 누구와 어떤 약속을 했는지 인물별로 기록하라.' } }));
    const result = await runUntilStored(f, lens.lensId, 1, 5);
    console.log(`recall chat lens: ${result.status} ${result.acceptedCount}`);
    console.log(`vectors: ${JSON.stringify(plain(await f.api.refreshLensVectors({ lensId: lens.lensId })))}`);
    return { seed: seedOf(f, 0), truth: plain(await f.api.inspectScopeLenses()), lensId: lens.lensId };
  } finally { await f.close(); }
};

// ---- 2. load into the shipped plugin in Chromium -------------------------------------------------
const marker = '  const publicApi = Object.freeze({\n    getHostLineageStatus: () => LibraMemoryCore';
const openPage = async (browser, seed, width) => {
  const page = await browser.newPage({ viewport: { width, height: width < 600 ? 844 : 900 } });
  page.setDefaultTimeout(20000);
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  // Embedding calls from the page go through Node (the key never enters the page's network log).
  await page.exposeFunction('__liveEmbed', async (url, body) => {
    const response = await fetch(url, { method: 'POST', headers: { Authorization: `Bearer ${process.env.RAG_EVAL_EMBED_KEY || ''}`, 'Content-Type': 'application/json' }, body });
    return { status: response.status, body: await response.text() };
  });
  await page.setContent('<html lang="ko"><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body></body></html>');
  await page.addScriptTag({ path: path.join(__dirname, '../../tests/browser/libra_writer_host.js') });
  await page.evaluate(data => {
    for (const [key, value] of data.seed.values) __writerHost.values.set(key, value);
    Object.assign(__writerHost.chat, data.seed.chat);
    Object.assign(__writerHost.character, data.seed.character);
    risuai.getCurrentChatIndex = async () => data.seed.index;
    risuai.getChatFromIndex = async (_c, i) => structuredClone(__writerHost.character.chats[i]);
    risuai.getChat = risuai.getCurrentChat = async () => structuredClone(__writerHost.character.chats[data.seed.index]);
    risuai.getDatabase = async () => structuredClone(data.persona);
    risuai.runLLMModel = async () => { throw new Error('the GUI check must not call the chat model'); };
    risuai.nativeFetch = async (url, init) => { const out = await __liveEmbed(String(url), String(init?.body || '')); return new Response(out.body, { status: out.status, headers: { 'Content-Type': 'application/json' } }); };
    globalThis.__replacers = {};
    risuai.addRisuReplacer = async (type, fn) => { __replacers[type] = fn; return true; };
  }, { seed, persona });
  const source = fs.readFileSync(path.join(__dirname, '../../plugins/LIBRA.js'), 'utf8');
  if (!source.includes(marker)) throw new Error('plugin marker not found');
  await page.addScriptTag({ content: source.replace(marker, '  globalThis.__approved={Gui,LibraMemoryCore,bookNavigate,selectBookMemoryKind,openApprovedPromptDialog};\n' + marker) });
  await page.waitForFunction(() => !!globalThis.__LIBRA__);
  await page.evaluate(() => __LIBRA__.openSettingsGui());
  await page.locator('.app[data-response-family="libra"]').waitFor();
  return { page, errors };
};
const touching = (page, scope) => page.evaluate(sel => {
  const out = [];
  const buttons = [...document.querySelectorAll(sel + ' button')].filter(button => button.getClientRects().length && button.offsetParent && !button.closest('.lens-nav'));
  for (let i = 0; i < buttons.length; i += 1) for (let j = i + 1; j < buttons.length; j += 1) {
    if (buttons[i].closest('.seg') && buttons[i].closest('.seg') === buttons[j].closest('.seg')) continue;
    const a = buttons[i].getBoundingClientRect(), b = buttons[j].getBoundingClientRect();
    if (Math.max(b.left - a.right, a.left - b.right) < 4 && Math.max(b.top - a.bottom, a.top - b.bottom) < 4) out.push([buttons[i].textContent.trim(), buttons[j].textContent.trim()]);
  }
  return out;
}, scope);
const overflow = page => page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);

// ---- 3. lens tab and studio against the engine's view --------------------------------------------
const checkReader = async (browser, data, width) => {
  const { page, errors } = await openPage(browser, data.seed, width);
  const tag = `[${width}px]`;
  try {
    const memories = data.truth.memories.filter(row => !row.inherited);
    await page.evaluate(() => { __approved.selectBookMemoryKind('lens'); __approved.bookNavigate('memory'); });
    await page.waitForSelector('[data-lens-reader] .lens-item');
    await page.waitForFunction(count => document.querySelectorAll('[data-lens-reader] .lens-item').length === count, memories.length).catch(() => {});
    const cards = await page.evaluate(() => [...document.querySelectorAll('[data-lens-reader] .lens-item')].map(card => ({
      id: card.dataset.lensItemId, lensId: card.dataset.lensId, text: card.querySelector('.lens-item__text')?.textContent || '', label: card.querySelector('.lens-label')?.textContent || '',
      quote: card.querySelector('.lens-quote span')?.textContent || '', who: card.querySelector('[data-lens-who]')?.dataset.lensWho || null,
      names: [...card.querySelectorAll('.lens-who__names > b')].map(node => node.firstChild?.textContent || ''), written: [...card.querySelectorAll('.lens-who__names small')].map(node => node.textContent),
      whoText: card.querySelector('[data-lens-who]')?.textContent || '', when: card.querySelector('[data-lens-when]')?.dataset.lensWhen || null, whenText: card.querySelector('[data-lens-when] b')?.textContent || '',
      whenRowText: card.querySelector('[data-lens-when]')?.textContent || '' })));
    check(`${tag} one card per stored note`, cards.length === memories.length, `${cards.length} cards / ${memories.length} notes`);
    let fieldErrors = [];
    for (const memory of memories) {
      const card = cards.find(row => row.id === memory.itemId && row.lensId === memory.lensId);
      if (!card) { fieldErrors.push(`missing card ${memory.itemId}`); continue; }
      if (norm(card.text) !== norm(memory.text)) fieldErrors.push(`text ${memory.itemId}`);
      if (norm(card.label) !== norm(memory.label)) fieldErrors.push(`label ${memory.itemId}`);
      if (memory.quote && norm(card.quote) !== norm(`“${memory.quote}”`)) fieldErrors.push(`quote ${memory.itemId}`);
      if (memory.whoTracked) {
        const expected = memory.people.map(person => person.name);
        if (!card.who) fieldErrors.push(`no person row ${memory.itemId}`);
        else if (expected.length ? card.who !== 'named' || JSON.stringify(card.names) !== JSON.stringify(expected) : card.who !== 'unknown' || !/인물 불명/.test(card.whoText)) fieldErrors.push(`person ${memory.itemId}: ${JSON.stringify(card.names)} vs ${JSON.stringify(expected)}`);
        for (const person of memory.people) if (person.written && person.written !== person.name && !card.written.includes(`원문: ${person.written}`)) fieldErrors.push(`written form ${memory.itemId}`);
        if (memory.people.some(person => person.role === 'user') && !/사용자 1인칭/.test(card.whoText)) fieldErrors.push(`user badge ${memory.itemId}`);
      } else if (card.who) fieldErrors.push(`unexpected person row ${memory.itemId}`);
      if (memory.whenTracked) {
        if (memory.when ? card.when !== 'stated' || card.whenText !== memory.when.text || !/원문 명시/.test(card.whenRowText) : card.when !== 'unknown' || !/시점 불명/.test(card.whenRowText)) fieldErrors.push(`time ${memory.itemId}: ${card.whenText} vs ${memory.when?.text || '불명'}`);
      } else if (card.when) fieldErrors.push(`unexpected time row ${memory.itemId}`);
    }
    check(`${tag} card fields equal the engine (text, label, quote, people, time)`, !fieldErrors.length, fieldErrors.slice(0, 6).join('; '));
    const extraKeys = await page.evaluate(() => [...document.querySelectorAll('[data-lens-reader] .lens-extra__pair b')].map(node => ({ shown: node.textContent.trim(), key: node.title })));
    const rawEnglish = extraKeys.filter(row => /^[A-Za-z]/.test(row.shown) && ['target', 'holder', 'clueStatus', 'clueType', 'suspect', 'reliability', 'sense', 'prop', 'place', 'tone', 'tension', 'speaker', 'listener', 'appellation', 'register', 'state'].includes(row.key));
    check(`${tag} extra values show Korean labels for known keys`, !rawEnglish.length, rawEnglish.slice(0, 4).map(row => row.shown).join(', '));

    // Person chips: built from the notes, with the engine's grouping and counts.
    const expectedChips = new Map();
    for (const memory of memories.filter(row => row.whoTracked)) for (const person of memory.people.length ? memory.people : [{ key: 'unknown', name: '인물 불명' }]) {
      const row = expectedChips.get(person.key) || { name: person.name, count: 0 }; row.count += 1; expectedChips.set(person.key, row);
    }
    const chips = await page.evaluate(() => [...document.querySelectorAll('[data-lens-people] [data-lens-person]')].map(node => ({ key: node.dataset.lensPerson, text: node.textContent.replace(/\s+/g, ' ').trim() })));
    const chipErrors = [];
    for (const [key, row] of expectedChips) { const chip = chips.find(item => item.key === key); if (!chip || chip.text !== `${row.name}${row.count}` && chip.text !== `${row.name} ${row.count}`) chipErrors.push(`${row.name} ${row.count} → ${chip?.text || 'missing'}`); }
    check(`${tag} person chips match the engine's grouping and counts`, !chipErrors.length && chips.length === expectedChips.size + 1, `${chipErrors.join('; ')} (${chips.length} chips)`);
    for (const [key, row] of [...expectedChips].slice(0, 4)) {
      await page.locator(`[data-lens-reader] [data-lens-person="${key}"]`).click();
      await page.waitForFunction(count => document.querySelectorAll('[data-lens-reader] .lens-item').length === count, row.count).catch(() => {});
      const shown = await page.locator('[data-lens-reader] .lens-item').count();
      check(`${tag} chip "${row.name}" filters to its ${row.count} notes`, shown === row.count, `${shown} shown`);
    }
    await page.locator('[data-lens-reader] [data-lens-person="all"]').click();
    await page.waitForFunction(count => document.querySelectorAll('[data-lens-reader] .lens-item').length === count, memories.length);

    // Every provenance fold: the quote, time and names are highlighted in the right turn.
    const provErrors = [];
    for (const memory of memories) {
      const card = page.locator(`[data-lens-reader] .lens-item[data-lens-item-id="${memory.itemId}"][data-lens-id="${memory.lensId}"]`);
      await card.locator('.lens-prov summary').click();
      await card.locator('.lens-prov .lens-ref').first().waitFor();
      const fold = await card.evaluate(node => ({ refs: [...node.querySelectorAll('.lens-prov .lens-ref')].map(ref => ({ ref: ref.dataset.lensRef, marks: [...ref.querySelectorAll('mark')].map(m => m.textContent), meta: ref.querySelector('.lens-meta')?.textContent || '' })),
        hints: [...node.querySelectorAll('.lens-prov .hint')].map(h => h.textContent) }));
      const refOf = ref => fold.refs.find(row => row.ref === ref);
      if (memory.quote && !(refOf(memory.quoteRef)?.marks || []).some(mark => norm(mark) === norm(memory.quote))) provErrors.push(`quote mark ${memory.itemId}`);
      if (memory.when && !(refOf(memory.when.ref)?.marks || []).some(mark => norm(mark).includes(norm(memory.when.text)))) provErrors.push(`time mark ${memory.itemId} (${memory.when.text} @${memory.when.ref})`);
      if (memory.when && !/시점이 적힌 턴/.test(refOf(memory.when.ref)?.meta || '')) provErrors.push(`time turn label ${memory.itemId}`);
      // A name inside the highlighted quote is shown by the quote's mark.
      for (const person of (memory.who || []).filter(row => row.role === 'named')) if (!(refOf(person.ref)?.marks || []).some(mark => norm(mark).includes(norm(person.name)))) provErrors.push(`name mark ${memory.itemId} (${person.name} @${person.ref})`);
      if (fold.hints.some(hint => /찾지 못해|불러오지 못했/.test(hint))) provErrors.push(`missing-source hint ${memory.itemId}`);
      await card.locator('.lens-prov summary').click();
    }
    check(`${tag} every provenance fold highlights the quote, time and names in their turns`, !provErrors.length, provErrors.slice(0, 6).join('; '));

    const name = [...expectedChips.values()].find(row => row.name !== '인물 불명')?.name || '';
    if (name) {
      await page.locator('[data-lens-reader] input[type="search"]').fill(name);
      const searched = await page.locator('[data-lens-reader] .lens-item').count();
      check(`${tag} search by a person's name ("${name}") finds their notes`, searched >= (expectedChips.get([...expectedChips].find(([, row]) => row.name === name)[0]).count), `${searched} shown`);
      await page.locator('[data-lens-reader] input[type="search"]').fill('');
    }
    check(`${tag} lens tab: no touching buttons`, !(await touching(page, '[data-lens-reader]')).length);
    check(`${tag} lens tab: no horizontal overflow`, (await overflow(page)) === 0);
    if (jsonOut) await page.locator('[data-lens-reader] .lens-item').filter({ has: page.locator('[data-lens-who]') }).first().screenshot({ path: path.join(path.dirname(jsonOut), `lens-gui-reader-${width}.png`) });

    // Studio: chips and the run log carry the engine's counts.
    await page.evaluate(() => __approved.openApprovedPromptDialog());
    await page.waitForSelector('#dlg-prompt [data-lens-card]');
    const studioErrors = [];
    for (const lensId of Object.values(data.lensIds)) {
      const lens = data.truth.registry.lenses.find(row => row.lensId === lensId);
      const text = await page.locator(`#dlg-prompt [data-lens-card="${lensId}"]`).innerText();
      if (lens.trackTime && !/시점 기록/.test(text)) studioErrors.push(`${lens.name}: no time chip`);
      if (lens.trackSubject && !/인물 구분/.test(text)) studioErrors.push(`${lens.name}: no people chip`);
    }
    // Each lens's run log is in its editor ("이 대화의 실행 기록").
    const runMeta = [];
    for (const lensId of Object.values(data.lensIds)) {
      await page.locator(`#dlg-prompt [data-lens-card="${lensId}"] button`, { hasText: '편집' }).click();
      await page.waitForSelector('#dlg-prompt [data-lens-editor] .lens-run');
      runMeta.push(...await page.evaluate(() => [...document.querySelectorAll('#dlg-prompt .lens-run .lens-meta')].map(node => node.textContent)));
      await page.locator('#dlg-prompt [data-lens-studio-view="list"]').click();
      await page.waitForSelector(`#dlg-prompt [data-lens-card="${lensId}"]`);
    }
    for (const run of data.truth.runs.filter(row => row.counts && row.status !== 'failed')) {
      const saved = Number(run.counts.quoted || 0) + Number(run.counts.interpreted || 0);
      const expected = [`저장 ${saved}`, run.counts.timeUnknown !== undefined ? `시점 명시 ${run.counts.timeStated}` : '', run.counts.subjectUnknown !== undefined ? `인물 확인 ${run.counts.subjectNamed}` : ''].filter(Boolean);
      if (!runMeta.some(meta => expected.every(part => meta.includes(part)))) studioErrors.push(`run ${run.lensName} T${run.turnRange.start}: ${expected.join(' · ')}`);
    }
    check(`${tag} studio cards and run log show the engine's settings and counts`, !studioErrors.length, studioErrors.join('; '));
    check(`${tag} studio: no touching buttons`, !(await touching(page, '#dlg-prompt')).length);
    check(`${tag} studio: no horizontal overflow`, (await page.evaluate(() => { const d = document.querySelector('#dlg-prompt .dialog'); return d.scrollWidth - d.clientWidth; })) === 0);
    check(`${tag} reader/studio: no page errors`, !errors.length, errors.join('; '));
  } finally { await page.close(); }
};

// ---- 4. recall: request hook → prompt → recall viewer ------------------------------------------
const checkRecall = async (browser, data, width) => {
  const { page, errors } = await openPage(browser, data.seed, width);
  const tag = `[${width}px]`;
  try {
    const query = '열쇠는 지금 누가 가지고 있고, 돌려주기로 한 약속은 어떻게 됐어?';
    const out = await page.evaluate(async text => {
      const messages = await __replacers.beforeRequest([{ role: 'user', content: text }], 'model');
      const system = messages.filter(message => message.role === 'system').map(message => String(message.content)).join('\n');
      const delivery = __approved.LibraMemoryCore.getLastRecall()?.delivery || null;
      return { system, lens: delivery?.lensRecall ? JSON.parse(JSON.stringify(delivery.lensRecall)) : null };
    }, query);
    const lines = out.system.split('\n').filter(line => line.startsWith('- [lens:'));
    check(`${tag} the request hook delivers lens lines`, lines.length > 0 && out.lens?.injected === true, `${lines.length} lines, injected ${out.lens?.injected}`);
    check(`${tag} delivered lines are the recall result's lines`, lines.length === (out.lens?.injectedItems || []).length && (out.lens?.injectedItems || []).every(item => out.system.includes(item.renderedLine.slice(2, 60))));
    check(`${tag} the semantic lane ran on the live embeddings`, out.lens?.semantic?.status === 'ready' && out.lens.semantic.scored > 0, JSON.stringify(out.lens?.semantic || {}));
    const tracked = (out.lens?.injectedItems || []).filter(item => item.record === undefined);
    check(`${tag} lens lines carry people and time`, lines.every(line => /인물: |인물 불명/.test(line) && /시점: |시점 불명/.test(line)), lines.slice(0, 2).join(' | '));
    report.recall = report.recall || { query, lines, semantic: out.lens?.semantic };

    await settings(page, 'logs');
    await page.locator('[data-execution-logs] .tabs button', { hasText: '리콜' }).click();
    await page.locator('[data-execution-logs="recall"] details.fold > summary', { hasText: '현재 턴 리콜 상세' }).click();
    await page.waitForFunction(() => [...document.querySelectorAll('[data-execution-logs="recall"] details')].some(node => node.querySelector(':scope > summary .badge')?.textContent === '렌즈 기억 (비정본)'));
    await page.evaluate(() => { const node = [...document.querySelectorAll('[data-execution-logs="recall"] details')].find(d => d.querySelector(':scope > summary .badge')?.textContent === '렌즈 기억 (비정본)'); node.setAttribute('data-lens-recall-panel', '1'); if (!node.open) node.querySelector(':scope > summary').click(); });
    await page.waitForFunction(() => document.querySelector('[data-lens-recall-panel] > .row'));
    const view = await page.evaluate(() => { const node = document.querySelector('[data-lens-recall-panel]'); return { summary: node.querySelector(':scope > summary')?.textContent || '', rows: [...node.querySelectorAll(':scope > .row')].map(row => row.textContent), hint: node.querySelector(':scope > p.hint')?.textContent || '' }; });
    const items = out.lens?.injectedItems || [];
    check(`${tag} recall viewer counts the delivered lens notes`, view.summary.includes(`전달 ${items.length}개`), view.summary);
    check(`${tag} recall viewer lists each delivered note with its score`, items.every(item => view.rows.some(row => row.includes(item.text.slice(0, 20)) && row.includes(`점수 ${Number(item.score).toFixed(2)}`))), view.rows.slice(0, 2).join(' | '));
    check(`${tag} recall viewer shows each note's people and time`, items.every(item => view.rows.some(row => row.includes(item.text.slice(0, 20))
      && (!Array.isArray(item.people) || row.includes(`인물 ${item.people.length ? item.people.join(', ') : '불명'}`)) && (typeof item.when !== 'string' || row.includes(`시점 ${item.when || '불명'}`)))), view.rows.slice(0, 1).join(''));
    check(`${tag} recall viewer shows the meaning scores`, items.filter(item => item.similarity !== null).every(item => view.rows.some(row => row.includes(`의미 ${Number(item.similarity).toFixed(2)}`))) && /의미 검색 사용/.test(view.hint), view.hint);
    check(`${tag} recall viewer: no horizontal overflow`, (await overflow(page)) === 0);
    const narrow = await page.evaluate(() => { const panel = document.querySelector('[data-lens-recall-panel]'); const width = panel.getBoundingClientRect().width;
      return [...panel.querySelectorAll(':scope > .row')].map(row => [...row.children].map(child => child.getBoundingClientRect().width)).filter(widths => widths.some(w => w < width * 0.5)).length; });
    check(`${tag} recall viewer rows use the panel width (no squeezed note text)`, narrow === 0, `${narrow} squeezed rows`);
    if (jsonOut) await page.locator('[data-lens-recall-panel]').screenshot({ path: path.join(path.dirname(jsonOut), `lens-gui-recall-${width}.png`) });
    check(`${tag} recall: no page errors`, !errors.length, errors.join('; '));
  } finally { await page.close(); }
};

(async () => {
  const corpusData = await generateCorpus();
  const recallData = await generateRecall();
  report.datasets = {
    corpus: { notes: corpusData.truth.memories.length, people: [...new Set(corpusData.truth.memories.flatMap(row => row.people.map(person => person.name)))], timed: corpusData.truth.memories.filter(row => row.when).length },
    recall: { notes: recallData.truth.memories.length }
  };
  console.log(JSON.stringify(report.datasets));
  const browser = await chromium.launch({ executablePath: process.env.CHROME_PATH || '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  try {
    for (const width of [1280, 390]) {
      await checkReader(browser, corpusData, width);
      await checkRecall(browser, recallData, width);
    }
  } finally { await browser.close(); }
  report.finishedAt = new Date().toISOString();
  if (jsonOut) fs.writeFileSync(jsonOut, JSON.stringify(report, null, 2), { mode: 0o600 });
  console.log(`checks ${report.checks.filter(row => row.ok).length}/${report.checks.length}`);
  if (report.failures.length) process.exitCode = 1;
})().catch(error => { console.error(error); process.exitCode = 1; });
